package media

import (
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// Storage keys are always generated by the CMS (spec 7.2: no user-supplied
// paths reach the filesystem). Layout under the media root:
//
//	private/o/<aa>/<bb>/<id>.<ext>   image originals (never served directly)
//	public/f/<id>/<safe-name>        downloadable files (PDF, audio, video ...)
//	public/v/<id>/<preset>.<fmt>     image variants
type Storage interface {
	Put(key string, r io.Reader) (int64, error)
	Open(key string) (io.ReadCloser, error)
	Delete(key string) error
	// LocalPath returns a filesystem path for processing tools (local storage only).
	LocalPath(key string) (string, error)
}

type Local struct{ Root string }

var ErrBadKey = errors.New("media: invalid storage key")

func (l *Local) path(key string) (string, error) {
	if key == "" || strings.Contains(key, "..") || strings.HasPrefix(key, "/") || strings.ContainsAny(key, "\\\x00") {
		return "", ErrBadKey
	}
	p := filepath.Join(l.Root, filepath.FromSlash(key))
	rel, err := filepath.Rel(l.Root, p)
	if err != nil || strings.HasPrefix(rel, "..") {
		return "", ErrBadKey
	}
	return p, nil
}

func (l *Local) Put(key string, r io.Reader) (int64, error) {
	p, err := l.path(key)
	if err != nil {
		return 0, err
	}
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		return 0, err
	}
	tmp, err := os.CreateTemp(filepath.Dir(p), ".up-*")
	if err != nil {
		return 0, err
	}
	n, err := io.Copy(tmp, r)
	if err == nil {
		err = tmp.Sync()
	}
	if cerr := tmp.Close(); err == nil {
		err = cerr
	}
	if err != nil {
		os.Remove(tmp.Name())
		return 0, err
	}
	if err := os.Chmod(tmp.Name(), 0o644); err != nil {
		os.Remove(tmp.Name())
		return 0, err
	}
	if err := os.Rename(tmp.Name(), p); err != nil {
		os.Remove(tmp.Name())
		return 0, err
	}
	return n, nil
}

// PutFile moves a finished temp file into place (same filesystem: no copy).
func (l *Local) PutFile(key, src string) error {
	p, err := l.path(key)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		return err
	}
	if err := os.Chmod(src, 0o644); err != nil {
		return err
	}
	if err := os.Rename(src, p); err == nil {
		return nil
	}
	f, err := os.Open(src)
	if err != nil {
		return err
	}
	defer f.Close()
	if _, err := l.Put(key, f); err != nil {
		return err
	}
	return os.Remove(src)
}

func (l *Local) Open(key string) (io.ReadCloser, error) {
	p, err := l.path(key)
	if err != nil {
		return nil, err
	}
	return os.Open(p)
}

func (l *Local) Delete(key string) error {
	p, err := l.path(key)
	if err != nil {
		return err
	}
	err = os.Remove(p)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	// Remove now-empty parent directories (best effort).
	for d := filepath.Dir(p); d != l.Root && strings.HasPrefix(d, l.Root); d = filepath.Dir(d) {
		if os.Remove(d) != nil {
			break
		}
	}
	return err
}

func (l *Local) LocalPath(key string) (string, error) { return l.path(key) }

func originalKey(id, ext string) string {
	return fmt.Sprintf("private/o/%s/%s/%s.%s", id[:2], id[2:4], id, ext)
}

func fileKey(id, name string) string { return fmt.Sprintf("public/f/%s/%s", id, name) }

func variantKey(id, preset, format string) string {
	return fmt.Sprintf("public/v/%s/%s.%s", id, preset, format)
}
